import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const repositoryRoot = fileURLToPath(new URL('../', import.meta.url));

const sourceConfigRelativePath = 'gallery-admin/wrangler.admin.local.jsonc';
const outputDirectoryRelativePath = 'gallery-admin/.wrangler';
const generatedBanner =
    '// Generated by scripts/prepare-gallery-phase-d-migration-configs.mjs. ' +
    'D1 migrations only; no Worker entry point. Do not deploy.\n';

const expectedAdminConfig = Object.freeze({
    schema: '../node_modules/wrangler/config-schema.json',
    workerName: 'family-running-gallery-admin-dev',
    main: 'src/admin-worker.js',
    compatibilityDate: '2026-08-25',
    cron: '0 * * * *',
    d1Binding: 'DB',
    d1Name: 'family-running-gallery-dev',
    privateOriginalsBinding: 'PRIVATE_ORIGINALS',
    privateOriginalsBucket: 'family-running-gallery-originals-dev'
});

const migrationFileNames = Object.freeze([
    '0001_private_gallery.sql',
    '0002_private_uploads.sql',
    '0003_private_original_v1_keys.sql',
    '0004_private_processing_staging.sql',
    '0005_private_processing_cleanup.sql',
    '0006_transition_receipt_state_version.sql'
]);

const outputPlans = Object.freeze([
    Object.freeze({
        fileName: 'gallery-phase-d-migration-0003.wrangler.jsonc',
        migrationNames: Object.freeze(['0003_private_original_v1_keys.sql']),
        migrationsPattern: '../migrations/0003_private_original_v1_keys.sql'
    }),
    Object.freeze({
        fileName: 'gallery-phase-d-migration-0004-0005.wrangler.jsonc',
        migrationNames: Object.freeze([
            '0004_private_processing_staging.sql',
            '0005_private_processing_cleanup.sql'
        ]),
        migrationsPattern:
            '../migrations/{0004_private_processing_staging.sql,' +
            '0005_private_processing_cleanup.sql}'
    }),
    Object.freeze({
        fileName: 'gallery-phase-d-migration-0006.wrangler.jsonc',
        migrationNames: Object.freeze([
            '0006_transition_receipt_state_version.sql'
        ]),
        migrationsPattern: '../migrations/0006_transition_receipt_state_version.sql'
    })
]);

const exactAdminTopLevelKeys = Object.freeze([
    '$schema',
    'account_id',
    'compatibility_date',
    'd1_databases',
    'main',
    'name',
    'observability',
    'preview_urls',
    'r2_buckets',
    'triggers',
    'workers_dev'
]);

const accountIdPattern = /^[0-9a-f]{32}$/;
const databaseIdPattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export async function prepareGalleryPhaseDMigrationConfigs({
    root = repositoryRoot,
    configPath = sourceConfigRelativePath,
    outputDirectory = outputDirectoryRelativePath,
    expectedAccountId,
    expectedDatabaseId
} = {}) {
    const absoluteRoot = path.resolve(root);
    await assertOrdinaryDirectory(absoluteRoot, 'repository root');

    const absoluteConfigPath = resolveExactRequestedPath(
        absoluteRoot,
        configPath,
        sourceConfigRelativePath,
        'source config'
    );
    const absoluteOutputDirectory = resolveExactRequestedPath(
        absoluteRoot,
        outputDirectory,
        outputDirectoryRelativePath,
        'output directory'
    );

    await validateIgnoredPathContract(absoluteRoot);
    await assertOrdinaryFile(absoluteConfigPath, 'source config');
    await validateMigrationDirectory(absoluteRoot);

    const sourceText = await fs.readFile(absoluteConfigPath, 'utf8');
    const sourceConfig = parseJsonc(sourceText, sourceConfigRelativePath);
    const sourceIdentity = validateAdminConfig(sourceConfig, {
        expectedAccountId,
        expectedDatabaseId
    });

    await ensureSafeOutputDirectory(absoluteRoot, absoluteOutputDirectory);

    const outputs = outputPlans.map(plan => {
        const config = buildMigrationConfig(sourceIdentity, plan);
        validateGeneratedMigrationConfig(config, sourceIdentity, plan);

        return {
            ...plan,
            absolutePath: path.join(absoluteOutputDirectory, plan.fileName),
            text: `${generatedBanner}${JSON.stringify(config, null, 2)}\n`
        };
    });

    for (const output of outputs) {
        await validateExistingOutput(output, sourceIdentity);
    }
    for (const output of outputs) {
        await fs.writeFile(output.absolutePath, output.text, {
            encoding: 'utf8',
            mode: 0o600
        });
        await assertOrdinaryFile(output.absolutePath, `generated output ${output.fileName}`);
    }

    return Object.freeze(outputs.map(output => Object.freeze({
        path: output.absolutePath,
        relativePath: toRepositoryRelativePath(absoluteRoot, output.absolutePath),
        migrationNames: output.migrationNames
    })));
}

export function parseJsonc(text, label = 'JSONC document') {
    if (typeof text !== 'string') {
        throw new Error(`${label} must be text.`);
    }

    const withoutBom = text.replace(/^\uFEFF/, '');
    const withoutComments = removeJsonComments(withoutBom, label);
    const withoutTrailingCommas = removeJsonTrailingCommas(withoutComments, label);

    try {
        return JSON.parse(withoutTrailingCommas);
    } catch (error) {
        throw new Error(`${label} is not valid JSONC: ${error.message}`);
    }
}

export function validateAdminConfig(config, {
    expectedAccountId,
    expectedDatabaseId
} = {}) {
    assertPlainObject(config, 'admin Wrangler config');
    assertExactKeys(config, exactAdminTopLevelKeys, 'admin Wrangler config');

    assertEqual(config.$schema, expectedAdminConfig.schema, '$schema');
    assertEqual(config.name, expectedAdminConfig.workerName, 'Worker name');
    assertEqual(config.main, expectedAdminConfig.main, 'Worker entry point');
    assertEqual(
        config.compatibility_date,
        expectedAdminConfig.compatibilityDate,
        'compatibility date'
    );
    assertEqual(config.workers_dev, true, 'workers_dev');
    assertEqual(config.preview_urls, false, 'preview_urls');

    assertPlainObject(config.observability, 'observability');
    assertExactKeys(config.observability, ['enabled'], 'observability');
    assertEqual(config.observability.enabled, false, 'observability.enabled');

    assertPlainObject(config.triggers, 'triggers');
    assertExactKeys(config.triggers, ['crons'], 'triggers');
    assertArray(config.triggers.crons, 'triggers.crons');
    assertEqual(config.triggers.crons.length, 1, 'triggers.crons length');
    assertEqual(config.triggers.crons[0], expectedAdminConfig.cron, 'cleanup cron');

    if (!accountIdPattern.test(config.account_id)) {
        throw new Error('account_id must be one populated canonical lowercase Cloudflare account ID.');
    }
    if (expectedAccountId !== undefined) {
        if (!accountIdPattern.test(expectedAccountId)) {
            throw new Error('The expected account ID is not canonical.');
        }
        assertEqual(config.account_id, expectedAccountId, 'expected account ID');
    }

    assertArray(config.d1_databases, 'd1_databases');
    assertEqual(config.d1_databases.length, 1, 'd1_databases length');
    const database = config.d1_databases[0];
    assertPlainObject(database, 'D1 binding');
    assertExactKeys(
        database,
        ['binding', 'database_id', 'database_name'],
        'D1 binding'
    );
    assertEqual(database.binding, expectedAdminConfig.d1Binding, 'D1 binding name');
    assertEqual(database.database_name, expectedAdminConfig.d1Name, 'D1 database name');
    if (!databaseIdPattern.test(database.database_id)) {
        throw new Error('database_id must be one populated canonical lowercase D1 UUID.');
    }
    if (expectedDatabaseId !== undefined) {
        if (!databaseIdPattern.test(expectedDatabaseId)) {
            throw new Error('The expected database ID is not canonical.');
        }
        assertEqual(database.database_id, expectedDatabaseId, 'expected database ID');
    }

    if ((expectedAccountId === undefined) !== (expectedDatabaseId === undefined)) {
        throw new Error(
            'Expected account and database IDs must be supplied together or both omitted.'
        );
    }

    assertArray(config.r2_buckets, 'r2_buckets');
    assertEqual(config.r2_buckets.length, 1, 'r2_buckets length');
    const bucket = config.r2_buckets[0];
    assertPlainObject(bucket, 'R2 binding');
    assertExactKeys(bucket, ['binding', 'bucket_name'], 'R2 binding');
    assertEqual(
        bucket.binding,
        expectedAdminConfig.privateOriginalsBinding,
        'private-originals binding'
    );
    assertEqual(
        bucket.bucket_name,
        expectedAdminConfig.privateOriginalsBucket,
        'private-originals bucket'
    );

    return Object.freeze({
        accountId: config.account_id,
        databaseId: database.database_id,
        databaseName: database.database_name,
        databaseBinding: database.binding
    });
}

function buildMigrationConfig(sourceIdentity, plan) {
    return {
        $schema: '../../node_modules/wrangler/config-schema.json',
        account_id: sourceIdentity.accountId,
        d1_databases: [
            {
                binding: sourceIdentity.databaseBinding,
                database_name: sourceIdentity.databaseName,
                database_id: sourceIdentity.databaseId,
                migrations_dir: '../migrations',
                migrations_pattern: plan.migrationsPattern
            }
        ]
    };
}

function validateGeneratedMigrationConfig(config, sourceIdentity, plan) {
    assertPlainObject(config, `generated config ${plan.fileName}`);
    assertExactKeys(
        config,
        ['$schema', 'account_id', 'd1_databases'],
        `generated config ${plan.fileName}`
    );
    assertEqual(
        config.$schema,
        '../../node_modules/wrangler/config-schema.json',
        `${plan.fileName} schema path`
    );
    assertEqual(config.account_id, sourceIdentity.accountId, `${plan.fileName} account ID`);
    assertArray(config.d1_databases, `${plan.fileName} d1_databases`);
    assertEqual(config.d1_databases.length, 1, `${plan.fileName} D1 binding count`);

    const database = config.d1_databases[0];
    assertPlainObject(database, `${plan.fileName} D1 binding`);
    assertExactKeys(database, [
        'binding',
        'database_id',
        'database_name',
        'migrations_dir',
        'migrations_pattern'
    ], `${plan.fileName} D1 binding`);
    assertEqual(database.binding, sourceIdentity.databaseBinding, `${plan.fileName} binding`);
    assertEqual(database.database_name, sourceIdentity.databaseName, `${plan.fileName} database`);
    assertEqual(database.database_id, sourceIdentity.databaseId, `${plan.fileName} database ID`);
    assertEqual(database.migrations_dir, '../migrations', `${plan.fileName} migrations_dir`);
    assertEqual(
        database.migrations_pattern,
        plan.migrationsPattern,
        `${plan.fileName} migrations_pattern`
    );
}

async function validateIgnoredPathContract(root) {
    const galleryAdminDirectory = path.join(root, 'gallery-admin');
    await assertOrdinaryDirectory(galleryAdminDirectory, 'gallery-admin directory');

    const ignorePath = path.join(galleryAdminDirectory, '.gitignore');
    await assertOrdinaryFile(ignorePath, 'gallery-admin ignore contract');
    const ignoreLines = (await fs.readFile(ignorePath, 'utf8'))
        .replace(/^\uFEFF/, '')
        .split(/\r?\n/)
        .map(line => line.trim())
        .filter(line => line && !line.startsWith('#'));

    for (const requiredRule of ['.wrangler/', 'wrangler.admin.local.jsonc']) {
        if (!ignoreLines.includes(requiredRule)) {
            throw new Error(
                `gallery-admin/.gitignore must contain the exact ${requiredRule} rule.`
            );
        }
    }
}

async function validateMigrationDirectory(root) {
    const migrationsDirectory = path.join(root, 'gallery-admin', 'migrations');
    await assertOrdinaryDirectory(migrationsDirectory, 'Gallery migration directory');
    const entries = await fs.readdir(migrationsDirectory, { withFileTypes: true });
    const actualNames = entries.map(entry => entry.name).sort();
    const expectedNames = [...migrationFileNames].sort();

    if (JSON.stringify(actualNames) !== JSON.stringify(expectedNames)) {
        throw new Error(
            'Gallery migration directory must contain exactly the reviewed 0001-0006 filenames.'
        );
    }

    for (const entry of entries) {
        if (!entry.isFile() || entry.isSymbolicLink()) {
            throw new Error(`Gallery migration ${entry.name} must be an ordinary file.`);
        }
        await assertOrdinaryFile(
            path.join(migrationsDirectory, entry.name),
            `Gallery migration ${entry.name}`
        );
    }
}

async function ensureSafeOutputDirectory(root, outputDirectory) {
    const expectedParent = path.join(root, 'gallery-admin');
    assertPathEqual(path.dirname(outputDirectory), expectedParent, 'output parent');

    try {
        await assertOrdinaryDirectory(outputDirectory, 'output directory');
    } catch (error) {
        if (error?.code !== 'ENOENT') {
            throw error;
        }
        await fs.mkdir(outputDirectory, { mode: 0o700 });
        await assertOrdinaryDirectory(outputDirectory, 'output directory');
    }
}

async function validateExistingOutput(output, sourceIdentity) {
    let stats;
    try {
        stats = await fs.lstat(output.absolutePath);
    } catch (error) {
        if (error?.code === 'ENOENT') {
            return;
        }
        throw error;
    }

    if (!stats.isFile() || stats.isSymbolicLink()) {
        throw new Error(`Refusing to replace non-file output ${output.fileName}.`);
    }

    const existingText = await fs.readFile(output.absolutePath, 'utf8');
    if (!existingText.startsWith(generatedBanner)) {
        throw new Error(`Refusing to replace unrecognized output ${output.fileName}.`);
    }
    const existingConfig = parseJsonc(existingText, output.fileName);
    validateGeneratedMigrationConfig(existingConfig, sourceIdentity, output);
}

function resolveExactRequestedPath(root, requestedPath, expectedRelativePath, label) {
    if (typeof requestedPath !== 'string' || !requestedPath.trim()) {
        throw new Error(`${label} must be a non-empty path.`);
    }
    if (requestedPath !== requestedPath.trim()) {
        throw new Error(`${label} must not contain surrounding whitespace.`);
    }
    if (requestedPath.split(/[\\/]/).some(segment => segment === '.' || segment === '..')) {
        throw new Error(`${label} must not contain traversal segments.`);
    }

    const resolved = path.resolve(root, requestedPath);
    const expected = path.resolve(root, expectedRelativePath);
    assertPathEqual(resolved, expected, label);
    return resolved;
}

async function assertOrdinaryDirectory(target, label) {
    const stats = await fs.lstat(target);
    if (!stats.isDirectory() || stats.isSymbolicLink()) {
        throw new Error(`${label} must be an ordinary directory.`);
    }
}

async function assertOrdinaryFile(target, label) {
    const stats = await fs.lstat(target);
    if (!stats.isFile() || stats.isSymbolicLink()) {
        throw new Error(`${label} must be an ordinary file.`);
    }
}

function removeJsonComments(text, label) {
    let output = '';
    let inString = false;
    let escaped = false;
    let inLineComment = false;
    let inBlockComment = false;

    for (let index = 0; index < text.length; index += 1) {
        const character = text[index];
        const next = text[index + 1];

        if (inLineComment) {
            if (character === '\n' || character === '\r') {
                inLineComment = false;
                output += character;
            } else {
                output += ' ';
            }
            continue;
        }
        if (inBlockComment) {
            if (character === '*' && next === '/') {
                output += '  ';
                index += 1;
                inBlockComment = false;
            } else {
                output += character === '\n' || character === '\r' ? character : ' ';
            }
            continue;
        }
        if (inString) {
            output += character;
            if (escaped) {
                escaped = false;
            } else if (character === '\\') {
                escaped = true;
            } else if (character === '"') {
                inString = false;
            }
            continue;
        }
        if (character === '"') {
            inString = true;
            output += character;
        } else if (character === '/' && next === '/') {
            inLineComment = true;
            output += '  ';
            index += 1;
        } else if (character === '/' && next === '*') {
            inBlockComment = true;
            output += '  ';
            index += 1;
        } else {
            output += character;
        }
    }

    if (inString || inBlockComment) {
        throw new Error(`${label} contains an unterminated string or block comment.`);
    }
    return output;
}

function removeJsonTrailingCommas(text, label) {
    let output = '';
    let inString = false;
    let escaped = false;

    for (let index = 0; index < text.length; index += 1) {
        const character = text[index];
        if (inString) {
            output += character;
            if (escaped) {
                escaped = false;
            } else if (character === '\\') {
                escaped = true;
            } else if (character === '"') {
                inString = false;
            }
            continue;
        }
        if (character === '"') {
            inString = true;
            output += character;
            continue;
        }
        if (character === ',') {
            let lookahead = index + 1;
            while (/\s/.test(text[lookahead] || '')) {
                lookahead += 1;
            }
            if (text[lookahead] === '}' || text[lookahead] === ']') {
                continue;
            }
        }
        output += character;
    }

    if (inString) {
        throw new Error(`${label} contains an unterminated string.`);
    }
    return output;
}

function assertPlainObject(value, label) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error(`${label} must be an object.`);
    }
    if (Object.getPrototypeOf(value) !== Object.prototype) {
        throw new Error(`${label} must be a plain object.`);
    }
}

function assertArray(value, label) {
    if (!Array.isArray(value)) {
        throw new Error(`${label} must be an array.`);
    }
}

function assertExactKeys(value, expectedKeys, label) {
    const actual = Object.keys(value).sort();
    const expected = [...expectedKeys].sort();
    if (JSON.stringify(actual) !== JSON.stringify(expected)) {
        throw new Error(
            `${label} has unexpected or missing fields: ${actual.join(', ') || '(none)'}.`
        );
    }
}

function assertEqual(actual, expected, label) {
    if (actual !== expected) {
        throw new Error(`${label} does not match the reviewed non-production contract.`);
    }
}

function assertPathEqual(actual, expected, label) {
    const normalizedActual = process.platform === 'win32' ? actual.toLowerCase() : actual;
    const normalizedExpected = process.platform === 'win32' ? expected.toLowerCase() : expected;
    if (normalizedActual !== normalizedExpected) {
        throw new Error(`${label} must resolve exactly to ${expected}.`);
    }
}

function toRepositoryRelativePath(root, target) {
    return path.relative(root, target).split(path.sep).join('/');
}

function parseArguments(argv) {
    const options = {};
    const accepted = new Map([
        ['--config', 'configPath'],
        ['--output-dir', 'outputDirectory'],
        ['--expected-account-id', 'expectedAccountId'],
        ['--expected-database-id', 'expectedDatabaseId']
    ]);

    for (let index = 0; index < argv.length; index += 1) {
        const argument = argv[index];
        if (argument === '--help') {
            return { help: true };
        }
        const property = accepted.get(argument);
        if (!property) {
            throw new Error(`Unknown argument: ${argument}`);
        }
        if (Object.hasOwn(options, property)) {
            throw new Error(`Argument repeated: ${argument}`);
        }
        const value = argv[index + 1];
        if (!value || value.startsWith('--')) {
            throw new Error(`Missing value for ${argument}.`);
        }
        options[property] = value;
        index += 1;
    }

    return options;
}

async function runCli() {
    const options = parseArguments(process.argv.slice(2));
    if (options.help) {
        console.log(
            'Usage: node scripts/prepare-gallery-phase-d-migration-configs.mjs ' +
            '[--config gallery-admin/wrangler.admin.local.jsonc] ' +
            '[--output-dir gallery-admin/.wrangler] ' +
            '[--expected-account-id ID --expected-database-id UUID]'
        );
        return;
    }

    const outputs = await prepareGalleryPhaseDMigrationConfigs(options);
    console.log('Prepared ignored, D1-only Phase D migration configs:');
    for (const output of outputs) {
        console.log(`- ${output.relativePath}: ${output.migrationNames.join(', ')}`);
    }
    console.log('No Worker entry point or non-D1 binding was written.');
}

const invokedPath = process.argv[1] ? pathToFileURL(path.resolve(process.argv[1])).href : '';
if (invokedPath === import.meta.url) {
    runCli().catch(error => {
        console.error(`Phase D migration config preparation failed: ${error.message}`);
        process.exitCode = 1;
    });
}
